function pretty(s, indent){ indent=indent||2; var o=JSON.parse(s); return JSON.stringify(o,null,indent); }
function minify(s){ var o=JSON.parse(s); return JSON.stringify(o); }
function tryParse(s){ try{ JSON.parse(s); return true; }catch(e){ return false; } }
var EXPORTS={pretty:pretty, minify:minify, tryParse:tryParse};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.JsonFormatterForgePure = EXPORTS; }
